/**
 * Rust code generator - consumes IR to generate idiomatic Rust
 */

import type { SchemaIR, StructIR, MethodIR, TypeIR, FieldIR } from '../schema_ir.js';

export class RustGenerator {
  generate(ir: SchemaIR): { types: string; api: string } {
    return {
      types: this.generateTypes(ir),
      api: this.generateApi(ir),
    };
  }

  private generateTypes(ir: SchemaIR): string {
    const parts: string[] = [
      '//! AUTOGENERATED - DO NOT EDIT',
      '//! Generated from Barretenberg msgpack schema',
      '',
      'use serde::{Deserialize, Serialize};',
      '',
      this.generateSerdeHelper(),
      '',
    ];

    // Generate all struct definitions
    const sortedStructs = Array.from(ir.structs.values()).sort((a, b) => a.name.localeCompare(b.name));
    for (const struct of sortedStructs) {
      parts.push(this.generateStruct(struct));
      parts.push('');
    }

    // Generate Command enum
    const commands = Array.from(ir.structs.values()).filter(s => s.isCommand);
    parts.push(this.generateCommandEnum(commands));
    parts.push('');

    // Generate Response enum
    const responses = ir.commands.map(cmd => cmd.returnType);
    parts.push(this.generateResponseEnum(responses, ir));
    parts.push('');

    return parts.join('\n');
  }

  private generateApi(ir: SchemaIR): string {
    const parts: string[] = [
      '//! AUTOGENERATED - DO NOT EDIT',
      '//! High-level Barretenberg API - msgpack details hidden',
      '',
      'use crate::backend::Backend;',
      'use crate::error::{BarretenbergError, Result};',
      'use crate::generated_types::*;',
      '',
      '/// High-level Barretenberg API',
      '///',
      '/// Hides all msgpack serialization details. Just call methods with Rust types.',
      '///',
      '/// # Example',
      '/// ```ignore',
      '/// use barretenberg_rs::{BarretenbergApi, backends::IpcBackend};',
      '///',
      '/// let backend = IpcBackend::new("/path/to/bb")?;',
      '/// let mut api = BarretenbergApi::new(backend);',
      '/// let hash = api.blake2s(b"hello")?;',
      '/// ```',
      'pub struct BarretenbergApi<B: Backend> {',
      '    backend: B,',
      '}',
      '',
      'impl<B: Backend> BarretenbergApi<B> {',
      '    /// Create API with custom backend',
      '    pub fn new(backend: B) -> Self {',
      '        Self { backend }',
      '    }',
      '',
      this.generateExecuteMethod(),
      '',
    ];

    // Generate all API methods
    for (const method of ir.commands) {
      // Skip Shutdown - handled specially
      if (method.originalName === 'Shutdown') continue;

      parts.push(this.generateApiMethod(method, ir));
      parts.push('');
    }

    // Add shutdown/destroy
    parts.push(
      '    /// Shutdown backend gracefully',
      '    pub fn shutdown(&mut self) -> Result<()> {',
      '        let cmd = Command::Shutdown(Shutdown::new());',
      '        let _ = self.execute(cmd)?;',
      '        self.backend.destroy()',
      '    }',
      '',
      '    /// Destroy backend without shutdown command',
      '    pub fn destroy(&mut self) -> Result<()> {',
      '        self.backend.destroy()',
      '    }',
      '}',
    );

    return parts.join('\n');
  }

  private generateStruct(struct: StructIR): string {
    const fields = struct.fields.map(f => this.generateField(f));

    // Only commands need the __typename field (for serialization)
    // Responses don't include it in BB's output
    const typenameField = struct.isCommand
      ? `    #[serde(rename = "__typename")]\n    pub type_name: String,\n`
      : '';

    const constructor = struct.isCommand ? this.generateConstructor(struct) : '';

    return `/// ${struct.name}\n` +
      `#[derive(Debug, Clone, Serialize, Deserialize)]\n` +
      `pub struct ${struct.name} {\n` +
      `${typenameField}` +
      `${fields.join('\n')}\n` +
      `}${constructor}`;
  }

  private generateField(field: FieldIR): string {
    let attrs = '';
    if (field.originalName !== field.name) {
      attrs += `    #[serde(rename = "${field.originalName}")]\n`;
    }
    if (this.needsSerdeBytes(field.type)) {
      attrs += `    #[serde(with = "serde_bytes")]\n`;
    }

    const rustType = this.typeToRust(field.type);
    return `${attrs}    pub ${field.name}: ${rustType},`;
  }

  private generateConstructor(struct: StructIR): string {
    const params = struct.fields.map(f => `${f.name}: ${this.typeToRust(f.type)}`).join(', ');
    const fieldInits = [
      `            type_name: "${struct.originalName}".to_string(),`,
      ...struct.fields.map(f => `            ${f.name},`),
    ];

    return `\n\nimpl ${struct.name} {\n` +
      `    pub fn new(${params}) -> Self {\n` +
      `        Self {\n` +
      `${fieldInits.join('\n')}\n` +
      `        }\n` +
      `    }\n` +
      `}`;
  }

  private generateApiMethod(method: MethodIR, ir: SchemaIR): string {
    // Make parameters ergonomic (use &[u8] instead of Vec<u8>)
    const params = method.params.map(p => {
      const ergonomicType = this.makeErgonomic(this.typeToRust(p.type));
      return `${p.name}: ${ergonomicType}`;
    }).join(', ');

    // Convert ergonomic params to owned types for constructor
    const paramConversions = method.params.map(p => {
      const rustType = this.typeToRust(p.type);
      return this.convertToOwned(p.name, rustType);
    }).join(', ');

    const commandType = this.toPascalCase(method.originalName);

    return `    /// ${method.doc || `Execute ${method.originalName}`}\n` +
      `    pub fn ${method.name}(&mut self, ${params}) -> Result<${method.returnType}> {\n` +
      `        let cmd = Command::${commandType}(${commandType}::new(${paramConversions}));\n` +
      `        match self.execute(cmd)? {\n` +
      `            Response::${method.returnType}(resp) => Ok(resp),\n` +
      `            _ => Err(BarretenbergError::InvalidResponse(\n` +
      `                "Expected ${method.returnType}".to_string()\n` +
      `            )),\n` +
      `        }\n` +
      `    }`;
  }

  private generateExecuteMethod(): string {
    return `    fn execute(&mut self, command: Command) -> Result<Response> {\n` +
      `        // BB expects an array of size 1 containing the command tuple\n` +
      `        // Use to_vec_named to ensure structs serialize as maps, not arrays\n` +
      `        let input_buffer = rmp_serde::to_vec_named(&vec![command])\n` +
      `            .map_err(|e| BarretenbergError::Serialization(e.to_string()))?;\n` +
      `\n` +
      `        let output_buffer = self.backend.call(&input_buffer)?;\n` +
      `\n` +
      `        let response: Response = rmp_serde::from_slice(&output_buffer)\n` +
      `            .map_err(|e| BarretenbergError::Deserialization(e.to_string()))?;\n` +
      `\n` +
      `        Ok(response)\n` +
      `    }`;
  }

  private generateCommandEnum(commands: StructIR[]): string {
    const variants = commands.map(c => `    ${c.name}(${c.name}),`).join('\n');
    const serializeCases = commands.map(c =>
      `            Command::${c.name}(data) => {\n` +
      `                tuple.serialize_element("${c.name}")?;\n` +
      `                tuple.serialize_element(data)?;\n` +
      `            }`
    ).join('\n');

    const deserializeCases = commands.map(c =>
      `                    "${c.name}" => {\n` +
      `                        let data = seq.next_element()?\n` +
      `                            .ok_or_else(|| serde::de::Error::invalid_length(1, &self))?;\n` +
      `                        Ok(Command::${c.name}(data))\n` +
      `                    }`
    ).join('\n');

    const variantNames = commands.map(c => `"${c.name}"`).join(', ');

    return `/// Command enum - wraps all possible commands\n` +
      `#[derive(Debug, Clone)]\n` +
      `pub enum Command {\n${variants}\n}\n\n` +
      this.generateSerdeImpl('Command', serializeCases, deserializeCases, variantNames);
  }

  private generateResponseEnum(responseTypes: string[], ir: SchemaIR): string {
    const uniqueTypes = [...new Set(responseTypes)];
    const variants = uniqueTypes.map(t => `    ${t}(${t}),`).join('\n');

    const serializeCases = uniqueTypes.map(t =>
      `            Response::${t}(data) => {\n` +
      `                tuple.serialize_element("${t}")?;\n` +
      `                tuple.serialize_element(data)?;\n` +
      `            }`
    ).join('\n');

    const deserializeCases = uniqueTypes.map(t =>
      `                    "${t}" => {\n` +
      `                        let data = seq.next_element()?\n` +
      `                            .ok_or_else(|| serde::de::Error::invalid_length(1, &self))?;\n` +
      `                        Ok(Response::${t}(data))\n` +
      `                    }`
    ).join('\n');

    const variantNames = uniqueTypes.map(t => `"${t}"`).join(', ');

    return `/// Response enum - wraps all possible responses\n` +
      `#[derive(Debug, Clone)]\n` +
      `pub enum Response {\n${variants}\n}\n\n` +
      this.generateSerdeImpl('Response', serializeCases, deserializeCases, variantNames);
  }

  private generateSerdeImpl(enumName: string, serializeCases: string, deserializeCases: string, variantNames: string): string {
    return `impl Serialize for ${enumName} {\n` +
      `    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>\n` +
      `    where S: serde::Serializer {\n` +
      `        use serde::ser::SerializeTuple;\n` +
      `        let mut tuple = serializer.serialize_tuple(2)?;\n` +
      `        match self {\n${serializeCases}\n        }\n` +
      `        tuple.end()\n` +
      `    }\n` +
      `}\n\n` +
      `impl<'de> Deserialize<'de> for ${enumName} {\n` +
      `    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>\n` +
      `    where D: serde::Deserializer<'de> {\n` +
      `        use serde::de::{SeqAccess, Visitor};\n` +
      `        struct ${enumName}Visitor;\n\n` +
      `        impl<'de> Visitor<'de> for ${enumName}Visitor {\n` +
      `            type Value = ${enumName};\n` +
      `            fn expecting(&self, formatter: &mut std::fmt::Formatter) -> std::fmt::Result {\n` +
      `                formatter.write_str("a 2-element array [name, payload]")\n` +
      `            }\n` +
      `            fn visit_seq<A>(self, mut seq: A) -> Result<Self::Value, A::Error>\n` +
      `            where A: SeqAccess<'de> {\n` +
      `                let name: String = seq.next_element()?\n` +
      `                    .ok_or_else(|| serde::de::Error::invalid_length(0, &self))?;\n` +
      `                match name.as_str() {\n${deserializeCases}\n` +
      `                    _ => Err(serde::de::Error::unknown_variant(&name, &[${variantNames}])),\n` +
      `                }\n` +
      `            }\n` +
      `        }\n` +
      `        deserializer.deserialize_tuple(2, ${enumName}Visitor)\n` +
      `    }\n` +
      `}`;
  }

  private generateSerdeHelper(): string {
    return `mod serde_bytes {\n` +
      `    use serde::{Deserialize, Deserializer, Serializer};\n` +
      `    pub fn serialize<S>(bytes: &Vec<u8>, serializer: S) -> Result<S::Ok, S::Error>\n` +
      `    where S: Serializer { serializer.serialize_bytes(bytes) }\n` +
      `    pub fn deserialize<'de, D>(deserializer: D) -> Result<Vec<u8>, D::Error>\n` +
      `    where D: Deserializer<'de> { <Vec<u8>>::deserialize(deserializer) }\n` +
      `}`;
  }

  private typeToRust(type: TypeIR): string {
    switch (type.kind) {
      case 'primitive':
        return type.name === 'bytes' ? 'Vec<u8>' : type.name!;
      case 'vec':
        return `Vec<${this.typeToRust(type.elementType!)}>`;
      case 'array':
        const elemType = this.typeToRust(type.elementType!);
        return type.size! > 32 ? `Vec<${elemType}>` : `[${elemType}; ${type.size}]`;
      case 'option':
        return `Option<${this.typeToRust(type.elementType!)}>`;
      case 'custom':
        return type.name!;
      default:
        return 'Unknown';
    }
  }

  private makeErgonomic(rustType: string): string {
    if (rustType === 'Vec<u8>') return '&[u8]';
    if (rustType === 'Vec<Vec<u8>>') return '&[Vec<u8>]';
    return rustType;
  }

  private convertToOwned(paramName: string, rustType: string): string {
    if (rustType === 'Vec<u8>' || rustType === 'Vec<Vec<u8>>') {
      return `${paramName}.to_vec()`;
    }
    return paramName;
  }

  private needsSerdeBytes(type: TypeIR): boolean {
    return type.kind === 'primitive' && type.name === 'bytes';
  }

  private toPascalCase(s: string): string {
    if (!s.includes('_') && s.charAt(0) === s.charAt(0).toUpperCase()) {
      return s;
    }
    return s.split('_').map(part =>
      part.charAt(0).toUpperCase() + part.slice(1).toLowerCase()
    ).join('');
  }
}
